public class FirstLast34{static int f(int[]a,int t){int l=0,r=a.length-1,ans=-1;while(l<=r){int m=l+(r-l)/2;if(a[m]==t){ans=m;r=m-1;}else if(a[m]<t)l=m+1;else r=m-1;}return ans;}static int g(int[]a,int t){int l=0,r=a.length-1,ans=-1;while(l<=r){int m=l+(r-l)/2;if(a[m]==t){ans=m;l=m+1;}else if(a[m]<t)l=m+1;else r=m-1;}return ans;}public static int[] searchRange(int[]a,int t){return new int[]{f(a,t),g(a,t)};}}